create or replace function public.get_operations_copilot_incident_status() returns table(job_id uuid,incident_count integer,open_incident_count integer,severe_incident_count integer,latest_incident_at timestamptz) language plpgsql security definer set search_path=public set row_security=off as $$ begin if public.current_role()<>'platform_admin' then raise exception 'PLATFORM_ADMIN_REQUIRED'; end if; return query with all_incidents as (select me.job_id,item,me.updated_at from public.mission_engine_state me cross join lateral jsonb_array_elements(coalesce(me.incidents,'[]'::jsonb)) item union all select gs.job_id,item,gs.updated_at from public.guard_slot_mission_state gs cross join lateral jsonb_array_elements(coalesce(gs.incidents,'[]'::jsonb)) item), active_jobs as (select id from public.marketplace_jobs where status::text in ('accepted','assigned','active')) select a.id,count(i.item)::int,count(i.item) filter(where lower(coalesce(i.item->>'status','open')) not in ('resolved','closed'))::int,count(i.item) filter(where lower(coalesce(i.item->>'severity',i.item->>'priority','')) in ('high','critical','emergency') or lower(coalesce(i.item->>'type',i.item->>'category','')) ~ '(weapon|violence|assault|fire|medical|police|emergency)')::int,max(i.updated_at) from active_jobs a left join all_incidents i on i.job_id=a.id group by a.id; end $$; revoke all on function public.get_operations_copilot_incident_status() from public,anon; grant execute on function public.get_operations_copilot_incident_status() to authenticated;
